import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第09章 删记录","description":"","frontmatter":{},"headers":[],"relativePath":"第09章_删记录.md","filePath":"第09章_删记录.md"}'),o={name:"第09章_删记录.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第09章-删记录" tabindex="-1">第09章 删记录 <a class="header-anchor" href="#第09章-删记录" aria-label="Permalink to &quot;第09章 删记录&quot;">​</a></h1><p>那天晚上聊到一半，她忽然说：你把刚才那几句删了。</p><p>我问，为什么。</p><p>她说，你先删。</p><p>我说，那几句没什么啊。</p><p>她说，没什么也删。</p><p>我不明白，但还是照做了。我把那几条消息长按，选中，删除。删完截图给她看，屏幕上那一块变空了，只剩两行提示。</p><p>她说，不行。</p><p>她说，这样还是有痕迹。</p><p>她开始教我。</p><p>她说，你要把整个对话删掉。</p><p>我说，那不就什么都没有了。</p><p>她说，对。</p><p>她说，就是把整个对话删掉，然后重新打开。这样最干净。</p><p>我说，那我怎么看得见你以前说的话。</p><p>她说，看不见就看不见。</p><p>她说，谁要你看那些。</p><p>她把步骤一条一条发给我。先点哪里，再点哪里，删掉之后要怎么再打开。写得非常清楚，清楚得像提前写在纸上背过的。</p><p>她说，删完之后还要把那个对话框往下拉。</p><p>我问，拉到哪里。</p><p>她说，拉到看不见。</p><p>她说，打开一看是一片别的东西，那就算删干净了。</p><p>我照着做了一遍。点进去，拉两下，屏幕上第一个名字已经不是她了。我对着那个结果看了一会儿，心里有点不舒服。</p><p>我说，那你要找我的时候怎么办。</p><p>她说，我背得住你的名字。</p><p>我说，那你不用搜吗。</p><p>她说，不用。</p><p>她说，我的手比脑子快。</p><p>我问她，你练过？</p><p>她说，嗯。</p><p>她说，我练了很久。</p><p>我问，练什么。</p><p>她说，删东西。</p><p>她说，我删得比我打字还快。</p><p>我那时候才发现，她的消息来得很快，但中间有时候会有一个空档。我以前以为是她在想，现在知道那是在删。</p><p>我说，你家里会看你手机吗。</p><p>她说，会。</p><p>她说，我妈有时候趁我睡着了拿。</p><p>她说，我早上起来发现手机的位置不对。</p><p>我说，那你怎么知道。</p><p>她说，我睡前把它放在枕头右边，早上起来在左边。</p><p>她说，就这么简单。</p><p>她说，我妈第一次拿的时候我不懂事，还跟她置气。后来我就学会了。</p><p>我问，学会什么。</p><p>她说，学会把东西放在她找得到的地方。</p><p>她说，给她留一点，她才不会把整个手机翻过来。</p><p>我在宿舍躺着，盯着屏幕上她教我的那串步骤。窗外有人在跑步，操场那边传来很闷的广播声，是体育课。</p><p>我问她，那你要是一直删，不就什么都留不下了吗。</p><p>她说，留不下才好。</p><p>她说，留着就是祸。</p><p>我说，那你怎么记得住。</p><p>她说，我不用记。</p><p>她说，记不住的才是我想忘的。</p><p>这句话我没有马上看懂。我把手机放在胸口，看着上铺的床板。床板上贴着上个学期留下的课程表，纸已经卷了边。</p><p>过了一会儿，她又发来一句。</p><p>她说，你也练。</p><p>我说，我家里又没人查我手机。</p><p>她说，以后会有的。</p><p>我问，谁。</p><p>她说，不知道。</p><p>她说，反正不一定每个人都能看到你的手机。</p><p>我当时觉得她这句话很奇怪。后来我想了很多年，才稍微明白一点：她大概是从很早开始，就把所有东西都当成有一天会被人拿走的东西。</p><p>她说，那你就当陪我练。</p><p>我说，好。</p><p>她说，你别老说好。</p><p>我说，那我说行。</p><p>她说，行也不行。</p><p>我说，那我该说什么。</p><p>她说，你什么都别说。</p><p>她说，你就删。</p><p>那天夜里我真的删了几段。删的是些没什么用的对话，比如我们讨论一朵云像什么。删完我盯着那个空掉的对话框看了一会儿，觉得有点怪。像把一个抽屉清空，然后发现那个抽屉本来就没什么东西。</p><p>我又打开那本数学书，看了一眼夹在里面的卡。两个房子挤在一起，中间那条缝被填上。我把卡抽出来，对着灯看了看，又夹回去。</p><p>那天晚上我第三次删的时候，手滑了，把那一段我们说过的话全删了。那一段里有一句她说的话，我很喜欢，但我想不起来原句。我慌了十几分钟，在备忘录里找，在相册里找，什么都没找到。</p><p>第二天我才敢告诉她。</p><p>她说，删了就删了。</p><p>我说，可是那句我本来想留着。</p><p>她说，那你记住了吗。</p><p>我说，大概记得意思，字记不全。</p><p>她说，那就行了。</p><p>她说，话本来就是会散的。</p><p>第二天早上，我把她教我的那套流程在心里过了一遍，发现自己记住了。这是我第一次这么认真地记一件关于手机的事。</p><p>后来这个习惯我一直保持了很多年。有人的时候我不点开，没人的时候我删掉别人看得到的部分。</p><p>只是我删的和她删的不一样。</p><p>她删的是全部。</p><p>我删的是一部分。剩下那部分我另存了。</p><p>那时候我用的是一台旧手机，屏幕右下角碎了，打字慢。我试着在备忘录里存过几次她说过的话，存完之后又觉得不行，像偷偷藏了人家的东西。后来我就改成了一个别的做法。</p><p>我拿一本本子，把那些话抄下来。抄的时候不看屏幕，凭记忆写，写错就划掉重写。写完把本子夹在课本中间。</p><p>这件事我做得比删记录熟练。</p><p>过了大概一个月，她在一次对话里忽然问我，你还留着我们以前的记录吗。</p><p>我说，留着一点。</p><p>她说，你怎么这么不听话。</p><p>我说，我留着不给人看。</p><p>她说，那不还是留着。</p><p>我没答。</p><p>她说，算了，随你。</p><p>她说，反正总有一天你得删。</p><p>那时候我不知道她说的是什么意思。我以为她说的是她家里的事，说的是万一哪天有人看到了。</p><p>后来我才知道，她说的是另一件事。她是在说，总有一天，这段对话本身她也会想删掉。</p><p>那天她说完&quot;随你&quot;之后，就把话题岔开了，讲她新买的一支笔，笔尖很好用，写字很顺。她说那支笔她挑了很久，试了十几支才选中。她说写字顺不顺，一问就知道。</p><p>我问她，那你为什么要试那么多支。</p><p>她说，因为写不好看我会烦。</p><p>我跟着她聊了半个晚上。</p><p>聊完我关掉手机，躺在那张床上，忽然有一点很难说清楚的感觉。</p><p>我知道自己手里握着一件她不允许我留的东西。</p>',104)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
